#focus-timer {
  position: fixed;
  bottom: 18px;
  right: 18px;
  z-index: 9999;
  background: var(--bg-alt);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  width: 230px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);
  font-family: var(--font-body);
}

#focus-timer header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  font-weight: 700;
}

#focus-timer .time-display {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  margin: 6px 0;
}

#focus-timer .controls {
  display: flex;
  gap: 8px;
}

#focus-timer button {
  flex: 1;
  background: var(--button-bg);
  color: var(--button-text);
  border: 1px solid var(--border);
  padding: 6px 10px;
  border-radius: 8px;
  cursor: pointer;
}

#focus-timer .presets {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 10px;
}

#focus-timer .preset {
  background: var(--bg);
  border: 1px dashed var(--border);
  padding: 6px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  text-align: center;
}

#focus-timer .preset:hover {
  background: var(--bg-alt);
}

#focus-timer .pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 0.9rem;
  background: var(--bg);
  border: 1px solid var(--border);
}

#focus-timer .progress {
  height: 6px;
  border-radius: 999px;
  background: var(--bg);
  border: 1px solid var(--border);
  overflow: hidden;
  margin-top: 10px;
}

#focus-timer .progress-inner {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent), var(--accent-contrast));
  transition: width 1s linear;
}

