(function() {
  'use strict';

  const api = window.CardSpoke.utils;
  const STORAGE_KEY = 'cs-focus-timer';
  let timerId = null;
  let endTime = null;

  function loadState() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY));
    } catch (err) {
      return null;
    }
  }

  function saveState(state) {
    try {
      if (state) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      } else {
        localStorage.removeItem(STORAGE_KEY);
      }
    } catch (err) {
      console.warn('Unable to save timer state', err);
    }
  }

  function formatTime(ms) {
    const totalSeconds = Math.max(0, Math.floor(ms / 1000));
    const minutes = String(Math.floor(totalSeconds / 60)).padStart(2, '0');
    const seconds = String(totalSeconds % 60).padStart(2, '0');
    return `${minutes}:${seconds}`;
  }

  function render({ remaining, label }) {
    const container = document.getElementById('focus-timer');
    if (!container) return;

    container.querySelector('.time-display').textContent = formatTime(remaining);
    container.querySelector('.pill .label').textContent = label || 'Custom';

    const bar = container.querySelector('.progress-inner');
    if (endTime) {
      const duration = endTime - (Date.now() - remaining);
      const progress = 1 - (remaining / duration);
      bar.style.width = `${Math.min(100, Math.max(0, progress * 100))}%`;
    } else {
      bar.style.width = '0%';
    }
  }

  function tick() {
    if (!endTime) return;
    const remaining = endTime - Date.now();

    if (remaining <= 0) {
      clearInterval(timerId);
      timerId = null;
      endTime = null;
      render({ remaining: 0, label: 'Complete' });
      api.showToast('Focus timer completed — nice work!', 'success');
      saveState(null);
      return;
    }

    render({ remaining, label: 'Running' });
  }

  function startTimer(minutes, label) {
    const duration = Math.max(1, minutes) * 60 * 1000;
    endTime = Date.now() + duration;
    render({ remaining: duration, label });

    if (timerId) clearInterval(timerId);
    timerId = setInterval(tick, 1000);

    saveState({ endTime, label });
    api.showToast(`Started ${label} timer for ${minutes} min`, 'info');
  }

  function stopTimer() {
    if (timerId) clearInterval(timerId);
    timerId = null;
    endTime = null;
    render({ remaining: 0, label: 'Stopped' });
    saveState(null);
  }

  function buildUi() {
    if (document.getElementById('focus-timer')) return;

    const container = document.createElement('section');
    container.id = 'focus-timer';
    container.innerHTML = `
      <header>
        <span>Focus Timer</span>
        <span class="pill">⏱️ <span class="label">Idle</span></span>
      </header>
      <div class="time-display">00:00</div>
      <div class="controls">
        <button data-action="start">Start</button>
        <button data-action="stop">Stop</button>
      </div>
      <div class="presets">
        <div class="preset" data-minutes="10" data-label="Sprint">10m</div>
        <div class="preset" data-minutes="25" data-label="Pomodoro">25m</div>
        <div class="preset" data-minutes="50" data-label="Deep">50m</div>
      </div>
      <div class="progress"><div class="progress-inner"></div></div>
    `;

    document.body.appendChild(container);

    container.querySelector('[data-action="start"]').addEventListener('click', () => startTimer(25, 'Manual'));
    container.querySelector('[data-action="stop"]').addEventListener('click', stopTimer);

    container.querySelectorAll('.preset').forEach(el => {
      el.addEventListener('click', () => {
        const minutes = Number(el.dataset.minutes);
        startTimer(minutes, el.dataset.label);
      });
    });
  }

  function hydrateFromStorage() {
    const state = loadState();
    if (!state || !state.endTime) return;
    if (state.endTime < Date.now()) {
      saveState(null);
      return;
    }

    endTime = state.endTime;
    render({ remaining: endTime - Date.now(), label: state.label || 'Running' });
    timerId = setInterval(tick, 1000);
  }

  buildUi();
  hydrateFromStorage();
  api.showToast('Focus Timer Plugin ready', 'success');
})();
